from __future__ import annotations

from decimal import Decimal, ROUND_HALF_UP
from typing import Any


class BusinessRuleViolation(Exception):
    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


_CENTS = Decimal("0.01")


def _nvl_number(value: Any, default: Any = 0) -> Decimal:
    """Apply legacy NVL numeric semantics: missing, None, and empty mean default."""
    if value is None or value == "":
        value = default
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _round_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def _is_deleted(row: dict) -> bool:
    return row.get("DEL_FLG", "") == "Y"


def transition_invoiced(
    order: dict, new_status: str
) -> tuple[dict, list[str], list[str]]:
    """Apply ORD-003 and the order_fulfilment I-to-X workflow transition."""
    if order["STAT_CD"] != "I":
        raise ValueError("transition_invoiced requires an invoiced order")

    if new_status == "X":
        updated_order = dict(order)
        updated_order["STAT_CD"] = "X"
        return updated_order, ["ORD_CANC_INV"], ["credit_note"]

    if new_status == "I":
        return dict(order), [], []

    raise BusinessRuleViolation(
        code="E5003",
        message="Invoiced order can only be cancelled",
    )


def recompute_total(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list[str]]:
    """
    Recompute live order-line extensions and the discounted order total.

    Invoiced and cancelled orders are frozen. Soft-deleted headers are excluded
    from recomputation, matching the legacy nightly query.
    """
    copied_order = dict(order)
    copied_lines = [dict(line) for line in lines]

    if copied_order["STAT_CD"] in ("I", "X") or _is_deleted(copied_order):
        return copied_order, copied_lines, []

    total = Decimal("0")

    for line in copied_lines:
        if _is_deleted(line):
            continue

        extension = _round_cents(
            _nvl_number(line.get("QTY")) * _nvl_number(line.get("UNIT_PRC"))
        )
        line["EXT_AMT"] = float(extension)
        total += extension

    discounted_total = _round_cents(
        total
        * (Decimal("100") - _nvl_number(copied_order.get("DISC_PCT")))
        / Decimal("100")
    )

    stored_total = _nvl_number(copied_order.get("TOT_AMT"))
    copied_order["TOT_AMT"] = float(discounted_total)

    audits = ["ORD_RETOTAL"] if stored_total != discounted_total else []
    return copied_order, copied_lines, audits
